pragma solidity >=0.8.0;

contract SenderTimestampProbe {
    uint256 public seen;
    uint256 public touches;
    address public lastBy;

    event Touched(uint256 seen, uint256 touches, address by);

    function snapshot() public {
        seen = block.timestamp;
        lastBy = msg.sender;
        touches += 1;
        emit Touched(seen, touches, msg.sender);
    }

    function touch() public {
        touches += 1;
        lastBy = msg.sender;
    }

    function getNow() public view returns (uint256) {
        return block.timestamp;
    }
}
